-- QuantDesk schema — TimescaleDB (PostgreSQL 16 + timescaledb 2.x)
-- Runs automatically on first boot via /docker-entrypoint-initdb.d.
--
-- This file is the Alembic BASELINE (revision 0001_baseline) and nothing more.
-- After first boot every change goes through a migration:
--
--     alembic revision -m "what you are changing"   # write the SQL by hand
--     qd migrate --sql                              # review it first
--     qd migrate                                    # apply it
--
-- Do NOT edit this file to make a schema change. A fresh install would get the
-- edit from initdb and an existing one would get it from the migration, so the
-- two would disagree the moment anybody forgets one of them. Never edit a live
-- DB by hand either.
--
-- Design notes live in ARCHITECTURE.md §3. The one invariant to remember:
--   `positions` MUST be reproducible by replaying `fills`.
--   qd-engine is the ONLY writer of orders/fills/positions.

CREATE EXTENSION IF NOT EXISTS timescaledb;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ════════════════════════════════════════════════════════════════════════
-- Enums
-- ════════════════════════════════════════════════════════════════════════
CREATE TYPE order_side     AS ENUM ('buy', 'sell');
CREATE TYPE order_type     AS ENUM ('market', 'limit', 'stop', 'stop_limit', 'oco');
CREATE TYPE order_status   AS ENUM ('pending', 'open', 'partial', 'filled',
                                    'cancelled', 'rejected', 'expired');
CREATE TYPE time_in_force  AS ENUM ('gtc', 'ioc', 'fok', 'post_only');
CREATE TYPE run_mode       AS ENUM ('backtest', 'paper', 'live');
CREATE TYPE market_regime  AS ENUM ('trending', 'ranging', 'crisis', 'unknown');

-- ════════════════════════════════════════════════════════════════════════
-- Market data (hypertables)
-- ════════════════════════════════════════════════════════════════════════

CREATE TABLE candles (
    exchange    text        NOT NULL,
    symbol      text        NOT NULL,
    timeframe   text        NOT NULL,          -- '1m','5m','1h','4h','1d'
    ts          timestamptz NOT NULL,          -- BAR OPEN time, UTC
    open        numeric(24,10) NOT NULL,
    high        numeric(24,10) NOT NULL,
    low         numeric(24,10) NOT NULL,
    close       numeric(24,10) NOT NULL,
    volume      numeric(28,10) NOT NULL,
    quote_volume numeric(28,10),
    trades      integer,
    vwap        numeric(24,10),
    -- Data-quality flags set by the collector's validation pass. Never silently
    -- drop a bad bar: mark it, so a backtest can decide what to do about it.
    is_gap_fill boolean     NOT NULL DEFAULT false,
    is_suspect  boolean     NOT NULL DEFAULT false,
    ingested_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (exchange, symbol, timeframe, ts)
);
SELECT create_hypertable('candles', 'ts', chunk_time_interval => interval '7 days');
ALTER TABLE candles SET (
    timescaledb.compress,
    timescaledb.compress_segmentby = 'exchange, symbol, timeframe',
    timescaledb.compress_orderby   = 'ts DESC'
);
SELECT add_compression_policy('candles', interval '7 days');
CREATE INDEX ON candles (symbol, timeframe, ts DESC);

-- Top-of-book, sampled. Used to calibrate the backtester's slippage model
-- against reality (ARCHITECTURE.md §7) and to fill PaperBroker orders.
CREATE TABLE book_snapshots (
    exchange  text        NOT NULL,
    symbol    text        NOT NULL,
    ts        timestamptz NOT NULL,
    bid       numeric(24,10) NOT NULL,
    ask       numeric(24,10) NOT NULL,
    bid_size  numeric(28,10),
    ask_size  numeric(28,10),
    PRIMARY KEY (exchange, symbol, ts)
);
SELECT create_hypertable('book_snapshots', 'ts', chunk_time_interval => interval '1 day');
ALTER TABLE book_snapshots SET (
    timescaledb.compress,
    timescaledb.compress_segmentby = 'exchange, symbol'
);
SELECT add_compression_policy('book_snapshots', interval '2 days');
SELECT add_retention_policy('book_snapshots', interval '90 days');

-- Recorded even though we do not trade perps, so the "is the basis trade worth
-- the jurisdiction hassle?" question can later be answered from data.
CREATE TABLE funding_rates (
    exchange text        NOT NULL,
    symbol   text        NOT NULL,
    ts       timestamptz NOT NULL,
    rate     numeric(18,10) NOT NULL,
    interval_hours integer NOT NULL DEFAULT 8,
    PRIMARY KEY (exchange, symbol, ts)
);
SELECT create_hypertable('funding_rates', 'ts', chunk_time_interval => interval '30 days');

-- ════════════════════════════════════════════════════════════════════════
-- Accounts, strategies, config
-- ════════════════════════════════════════════════════════════════════════

CREATE TABLE accounts (
    id            serial PRIMARY KEY,
    name          text UNIQUE NOT NULL,
    mode          run_mode    NOT NULL,
    exchange      text        NOT NULL,
    quote_ccy     text        NOT NULL DEFAULT 'USD',
    initial_equity numeric(20,8) NOT NULL,
    high_water_mark numeric(20,8) NOT NULL DEFAULT 0,
    created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE strategies (
    id          serial PRIMARY KEY,
    name        text UNIQUE NOT NULL,          -- 'ema_cross'
    class_path  text        NOT NULL,          -- 'ct.strategies.trend:EmaCrossStrategy'
    enabled     boolean     NOT NULL DEFAULT false,
    -- 'active' | 'quarantined' (crashed) | 'paused' (loss breaker)
    status      text        NOT NULL DEFAULT 'active',
    status_reason text,
    paused_until timestamptz,
    params      jsonb       NOT NULL DEFAULT '{}'::jsonb,
    params_hash text        NOT NULL,
    symbols     text[]      NOT NULL DEFAULT '{}',
    timeframe   text        NOT NULL DEFAULT '4h',
    weight      numeric(8,6) NOT NULL DEFAULT 0.0,   -- portfolio allocation
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE risk_config (
    id            serial PRIMARY KEY,
    account_id    integer NOT NULL REFERENCES accounts(id),
    -- Full RiskLimits dataclass, versioned. The engine reads the newest row.
    limits        jsonb   NOT NULL,
    effective_from timestamptz NOT NULL DEFAULT now(),
    created_by    text    NOT NULL,
    note          text
);
CREATE INDEX ON risk_config (account_id, effective_from DESC);

-- ════════════════════════════════════════════════════════════════════════
-- Signals — INCLUDING rejected ones. Without the rejections you cannot tell
-- "the strategy is bad" from "risk is strangling it". §3.
-- ════════════════════════════════════════════════════════════════════════
CREATE TABLE signals (
    id          bigserial,
    ts          timestamptz NOT NULL,
    account_id  integer     NOT NULL REFERENCES accounts(id),
    strategy    text        NOT NULL,
    symbol      text        NOT NULL,
    direction   smallint    NOT NULL,           -- +1 long, -1 short, 0 flat/exit
    strength    numeric(8,6) NOT NULL DEFAULT 1.0,
    ref_price   numeric(24,10),
    stop_price  numeric(24,10),
    target_price numeric(24,10),
    regime      market_regime NOT NULL DEFAULT 'unknown',
    ml_confidence numeric(8,6),                 -- meta-labeller p(win), nullable
    accepted    boolean     NOT NULL,
    reject_code text,                           -- 'GROSS_EXPOSURE_CAP', ...
    reject_detail text,
    sized_qty   numeric(28,10),
    meta        jsonb NOT NULL DEFAULT '{}'::jsonb,
    PRIMARY KEY (id, ts)
);
SELECT create_hypertable('signals', 'ts', chunk_time_interval => interval '30 days');
CREATE INDEX ON signals (strategy, ts DESC);
CREATE INDEX ON signals (accepted, ts DESC);

-- ════════════════════════════════════════════════════════════════════════
-- Orders / fills / positions — qd-engine is the sole writer.
-- ════════════════════════════════════════════════════════════════════════

CREATE TABLE orders (
    id              bigserial PRIMARY KEY,
    -- Idempotency key. Generated BEFORE the API call; on restart every
    -- non-terminal order is re-queried by this id before anything new is sent.
    client_order_id text        UNIQUE NOT NULL,
    exchange_order_id text,
    account_id      integer     NOT NULL REFERENCES accounts(id),
    strategy        text        NOT NULL,
    signal_id       bigint,
    symbol          text        NOT NULL,
    side            order_side  NOT NULL,
    type            order_type  NOT NULL,
    tif             time_in_force NOT NULL DEFAULT 'gtc',
    qty             numeric(28,10) NOT NULL CHECK (qty > 0),
    limit_price     numeric(24,10),
    stop_price      numeric(24,10),
    status          order_status NOT NULL DEFAULT 'pending',
    filled_qty      numeric(28,10) NOT NULL DEFAULT 0,  -- derived from fills
    avg_fill_price  numeric(24,10),
    fee_paid        numeric(20,10) NOT NULL DEFAULT 0,
    reduce_only     boolean     NOT NULL DEFAULT false,
    -- Attached protective levels. Also enforced engine-side every bar; we do
    -- not rely on the venue honouring a resting stop. §6.2
    attached_stop   numeric(24,10),
    attached_target numeric(24,10),
    trail_atr_mult  numeric(10,4),
    created_at      timestamptz NOT NULL DEFAULT now(),
    submitted_at    timestamptz,
    terminal_at     timestamptz,
    error_code      text,
    error_detail    text,
    meta            jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX ON orders (account_id, status) WHERE status IN ('pending','open','partial');
CREATE INDEX ON orders (symbol, created_at DESC);
CREATE INDEX ON orders (strategy, created_at DESC);

CREATE TABLE fills (
    id           bigserial PRIMARY KEY,
    order_id     bigint      NOT NULL REFERENCES orders(id),
    exchange_fill_id text,
    ts           timestamptz NOT NULL,
    qty          numeric(28,10) NOT NULL CHECK (qty > 0),
    price        numeric(24,10) NOT NULL,
    fee          numeric(20,10) NOT NULL DEFAULT 0,
    fee_ccy      text,
    is_maker     boolean,
    UNIQUE (order_id, exchange_fill_id)
);
CREATE INDEX ON fills (ts DESC);

-- One row per BOOK — (account, strategy, symbol) — not per symbol.
--
-- The PK deliberately includes `strategy`. With more than one strategy trading
-- a symbol, a symbol-keyed position forces them to share one book, so a close
-- from strategy A flattens strategy B's trade. That is the "strategies fighting
-- over capital" failure the allocator exists to prevent, and it has to be
-- impossible in the schema rather than merely discouraged in code. Mirrors
-- `AccountState.book_key` exactly.
--
-- Exposure and correlation caps still aggregate by SYMBOL, because that is what
-- the exchange holds — see `positions_by_symbol` below.
CREATE TABLE positions (
    account_id   integer NOT NULL REFERENCES accounts(id),
    strategy     text    NOT NULL,
    symbol       text    NOT NULL,
    qty          numeric(28,10) NOT NULL DEFAULT 0,     -- signed; + long
    avg_entry    numeric(24,10) NOT NULL DEFAULT 0,
    realized_pnl numeric(20,10) NOT NULL DEFAULT 0,
    fees_paid    numeric(20,10) NOT NULL DEFAULT 0,
    stop_price   numeric(24,10),
    target_price numeric(24,10),
    trail_atr_mult numeric(10,4),
    highest_close numeric(24,10),   -- for the trailing stop
    lowest_close  numeric(24,10),
    opened_at    timestamptz,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (account_id, strategy, symbol)
);
CREATE INDEX ON positions (account_id, symbol);

-- What risk actually reasons about: net exposure per symbol across every book.
CREATE OR REPLACE VIEW positions_by_symbol AS
SELECT account_id, symbol,
       sum(qty)                              AS net_qty,
       sum(abs(qty))                         AS gross_qty,
       count(*) FILTER (WHERE qty <> 0)      AS open_books,
       sum(realized_pnl)                     AS realized_pnl,
       sum(fees_paid)                        AS fees_paid
FROM positions
GROUP BY account_id, symbol;

-- Closed round-trips, materialised by the engine when a position returns to 0.
-- This is what the metrics module consumes; deriving it on the fly from fills
-- in every query was measurably slow on the N100.
CREATE TABLE trades (
    id           bigserial PRIMARY KEY,
    account_id   integer NOT NULL REFERENCES accounts(id),
    strategy     text    NOT NULL,
    symbol       text    NOT NULL,
    direction    smallint NOT NULL,
    qty          numeric(28,10) NOT NULL,
    entry_ts     timestamptz NOT NULL,
    exit_ts      timestamptz NOT NULL,
    entry_price  numeric(24,10) NOT NULL,
    exit_price   numeric(24,10) NOT NULL,
    gross_pnl    numeric(20,10) NOT NULL,
    fees         numeric(20,10) NOT NULL,
    net_pnl      numeric(20,10) NOT NULL,
    return_pct   numeric(14,8)  NOT NULL,
    bars_held    integer,
    exit_reason  text,          -- 'signal','stop','trail','target','flatten','risk'
    mae          numeric(14,8), -- max adverse excursion
    mfe          numeric(14,8)  -- max favourable excursion
);
CREATE INDEX ON trades (strategy, exit_ts DESC);
CREATE INDEX ON trades (account_id, exit_ts DESC);

CREATE TABLE equity_curve (
    account_id  integer     NOT NULL REFERENCES accounts(id),
    ts          timestamptz NOT NULL,
    equity      numeric(20,8) NOT NULL,
    cash        numeric(20,8) NOT NULL,
    positions_value numeric(20,8) NOT NULL,
    unrealized_pnl  numeric(20,8) NOT NULL DEFAULT 0,
    gross_exposure  numeric(10,6) NOT NULL DEFAULT 0,
    drawdown        numeric(10,6) NOT NULL DEFAULT 0,
    PRIMARY KEY (account_id, ts)
);
SELECT create_hypertable('equity_curve', 'ts', chunk_time_interval => interval '30 days');

-- ════════════════════════════════════════════════════════════════════════
-- Control plane & safety
-- ════════════════════════════════════════════════════════════════════════

CREATE TABLE risk_events (
    id         bigserial PRIMARY KEY,
    ts         timestamptz NOT NULL DEFAULT now(),
    account_id integer REFERENCES accounts(id),
    severity   text    NOT NULL,   -- 'info' | 'warn' | 'critical'
    code       text    NOT NULL,   -- 'DAILY_DD_HALT', 'RECONCILE_MISMATCH', ...
    detail     text,
    payload    jsonb   NOT NULL DEFAULT '{}'::jsonb,
    resolved_at timestamptz
);
CREATE INDEX ON risk_events (ts DESC);
CREATE INDEX ON risk_events (severity, ts DESC) WHERE resolved_at IS NULL;

-- The ONLY table qd-web may write. The engine polls it. §1 merge 1.
CREATE TABLE control_commands (
    id          bigserial PRIMARY KEY,
    ts          timestamptz NOT NULL DEFAULT now(),
    account_id  integer REFERENCES accounts(id),
    -- Mirrors VALID_COMMANDS in ct/engine/control.py. BOTH must change
    -- together, and a deployed database needs an ALTER: adding
    -- resolve_risk_event to the code alone failed live against this CHECK
    -- (2026-07-30) — the code-level allowlist and this constraint are one
    -- boundary expressed twice.
    command     text NOT NULL CHECK (command IN
                  ('halt','resume','flatten_symbol','flatten_all',
                   'pause_strategy','resume_strategy','reload_config',
                   'resolve_risk_event')),
    args        jsonb NOT NULL DEFAULT '{}'::jsonb,
    requested_by text NOT NULL,
    applied_at  timestamptz,
    result      text
);
CREATE INDEX ON control_commands (applied_at) WHERE applied_at IS NULL;

-- Append-only. Live trading is impossible without a valid unexpired row here,
-- and `QD_MODE=live` alone is NOT sufficient. ARCHITECTURE.md §8.4.
--
-- THE INVARIANT: every arming chain must terminate in a human tap.
--   origin='human'      → created by `qd arm-live` or a Telegram approval tap.
--                         renews_id IS NULL. This is the root of a chain.
--   origin='auto_renew' → created by the engine to extend an arming whose
--                         envelope has not changed. MUST reference a parent.
--
-- `is_human_rooted()` walks the chain to its root; the engine calls it before
-- every live order, so renewal can never manufacture authority a human did not
-- originate.
--
-- `envelope_hash` binds a renewal to unchanged terms: sha256 over
-- (account, symbols, strategies, caps, risk_config id, code_git_sha). Any change
-- to any of them breaks the hash and renewal is refused — a fresh human tap is
-- required. That is what makes indefinite renewal safe: it renews *the same
-- decision*, never a new one.
CREATE TABLE live_arming (
    id                bigserial PRIMARY KEY,
    account_id        integer NOT NULL REFERENCES accounts(id),
    armed_at          timestamptz NOT NULL DEFAULT now(),
    expires_at        timestamptz NOT NULL,
    armed_by          text NOT NULL,
    origin            text NOT NULL DEFAULT 'human'
                        CHECK (origin IN ('human', 'auto_renew')),
    renews_id         bigint REFERENCES live_arming(id),
    envelope_hash     text NOT NULL,
    confirmation_hash text,
    max_notional_usd  numeric(20,8) NOT NULL,
    max_daily_notional_usd numeric(20,8) NOT NULL,
    allowed_symbols   text[] NOT NULL,
    allowed_strategies text[] NOT NULL,
    gate_forced       boolean NOT NULL DEFAULT false,  -- promotion gate bypassed
    disarmed_at       timestamptz,
    disarmed_by       text,
    disarm_reason     text,
    -- A human arming carries a typed confirmation and has no parent.
    CONSTRAINT human_arming_is_rooted CHECK (
        origin <> 'human' OR (renews_id IS NULL AND confirmation_hash IS NOT NULL)),
    -- A renewal MUST have a parent. Enforced in the schema, not only in code,
    -- so no future refactor can produce an orphan renewal that trades.
    CONSTRAINT renewal_must_have_parent CHECK (
        origin <> 'auto_renew' OR renews_id IS NOT NULL)
);
CREATE INDEX ON live_arming (account_id, expires_at DESC);
CREATE INDEX ON live_arming (renews_id);

-- Walk a renewal chain to its root and confirm (a) a human started it and
-- (b) NO row anywhere in the chain has been disarmed.
--
-- The disarm check on ANCESTORS is not optional and was not obvious: a renewal
-- is a separate row with its own disarmed_at, so disarming the root alone left
-- every child still "active" and the system kept trading through a drawdown
-- halt. Caught by test T5 on 2026-07-27 against a real Postgres — the schema
-- looked correct and was not. Disarm must poison the whole lineage.
--
-- Expiry is deliberately checked only on the LEAF (in `active_arming`): a
-- renewal's entire purpose is to extend past its parent's expiry.
--
-- Depth-capped: a cycle (reachable only via manual DB surgery) returns false
-- rather than looping forever. Refusing to trade is the safe failure direction.
CREATE OR REPLACE FUNCTION arming_is_valid(arming_id bigint)
RETURNS boolean LANGUAGE plpgsql STABLE AS $$
DECLARE
    cur   bigint := arming_id;
    row_  live_arming%ROWTYPE;
    hops  integer := 0;
BEGIN
    WHILE cur IS NOT NULL AND hops < 1000 LOOP
        SELECT * INTO row_ FROM live_arming WHERE id = cur;
        IF NOT FOUND THEN
            RETURN false;                      -- broken lineage
        END IF;
        IF row_.disarmed_at IS NOT NULL THEN
            RETURN false;                      -- disarm poisons descendants
        END IF;
        IF row_.origin = 'human' THEN
            RETURN row_.confirmation_hash IS NOT NULL;
        END IF;
        cur  := row_.renews_id;
        hops := hops + 1;
    END LOOP;
    RETURN false;                              -- cycle or orphan
END;
$$;

-- The single question the engine asks before every live order:
--   SELECT * FROM active_arming WHERE account_id = $1;
-- DISTINCT ON collapses a renewal chain to the one row that currently governs,
-- so caps are read once rather than summed across the lineage.
CREATE OR REPLACE VIEW active_arming AS
SELECT DISTINCT ON (a.account_id) a.*
FROM live_arming a
WHERE a.disarmed_at IS NULL
  AND a.expires_at > now()
  AND arming_is_valid(a.id)
ORDER BY a.account_id, a.armed_at DESC, a.id DESC;

-- Transactional outbox: written in the SAME transaction as the fill it
-- announces, so "traded but never notified" cannot happen. §1 merge 3.
CREATE TABLE notifications (
    id         bigserial PRIMARY KEY,
    ts         timestamptz NOT NULL DEFAULT now(),
    channel    text NOT NULL,          -- 'telegram' | 'discord' | 'email'
    priority   text NOT NULL DEFAULT 'normal',  -- 'silent'|'normal'|'loud'
    subject    text,
    body       text NOT NULL,
    status     text NOT NULL DEFAULT 'pending', -- pending|sent|failed|dropped
    attempts   integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    sent_at    timestamptz,
    last_error text
);
CREATE INDEX ON notifications (status, next_attempt_at) WHERE status = 'pending';

-- ════════════════════════════════════════════════════════════════════════
-- Event log — the append-only spine for replay, audit and the dashboard feed.
--
-- Mirrors `ct/events/log.py`'s JSONL format exactly, so the file log and this
-- table are two sinks for one shape and a run can be replayed from either.
--
-- `seq` is assigned by the bus (the only sequencer), globally unique and
-- monotonic ACROSS RESTARTS — the bus recovers its high-water mark on boot.
--
-- ── Why this is NOT a hypertable, unlike every other time series here ──
--
-- TimescaleDB refuses a UNIQUE index that does not include the partitioning
-- column: `CREATE UNIQUE INDEX ON events (seq)` fails with
--   "cannot create a unique index without the column ts (used in partitioning)"
-- (verified against timescaledb 2.17.2-pg16, 2026-07-27). The best a hypertable
-- allows is UNIQUE (seq, ts) — which permits the same `seq` at two different
-- timestamps, and that is precisely the corruption worth preventing. Two
-- qd-engine containers running at once (split brain), or a bus that failed to
-- recover its high-water mark, would both silently produce duplicate sequences
-- and quietly break every replay that spans them.
--
-- The trade is disk, and disk is not the scarce resource here: ~3k events/day
-- (heartbeats dominate) is ~1.1M rows and well under a GB per year, against
-- 15 TB free. RAM is what is scarce on this NAS, and a plain table uses less of
-- it than a hypertable's chunk metadata. A BRIN index on `ts` is near-free and
-- ideal for append-only data whose physical order matches its time order.
--
-- If event volume ever justifies partitioning, converting is a migration — and
-- at that point the uniqueness guarantee moves to the application layer and
-- gets weaker. Do it deliberately, not by reflex.
--
-- NOTHING may UPDATE or DELETE from this table. It is the record of what
-- happened. Retention is by archiving whole date ranges out, never by editing.
-- ════════════════════════════════════════════════════════════════════════
CREATE TABLE events (
    seq            bigint      PRIMARY KEY,   -- globally unique; see above
    ts             timestamptz NOT NULL,
    type           text        NOT NULL,   -- EventType value, e.g. 'execution.order_filled'
    source         text        NOT NULL DEFAULT 'unknown',
    severity       text        NOT NULL DEFAULT 'info'
                     CHECK (severity IN ('debug','info','warning','critical')),
    -- Groups one trade lifecycle: signal → risk → order → fill → close.
    correlation_id text,
    -- The event that caused this one; lets replay build a causal tree.
    causation_id   bigint,
    payload        jsonb       NOT NULL DEFAULT '{}'::jsonb
);
-- BRIN, not BTREE: append-only + time-ordered means a BRIN index is a few KB
-- where a BTREE would be tens of MB, for the same range-scan performance.
CREATE INDEX events_ts_brin ON events USING brin (ts) WITH (pages_per_range = 64);
CREATE INDEX ON events (correlation_id, seq) WHERE correlation_id IS NOT NULL;
CREATE INDEX ON events (type, seq DESC);
CREATE INDEX ON events (seq DESC) WHERE severity IN ('warning', 'critical');
-- GIN on the payload so the dashboard can filter by symbol/strategy without a
-- column per field.
CREATE INDEX ON events USING gin (payload jsonb_path_ops);

-- Trade lifecycles, ready-made for the dashboard's replay and execution
-- timeline views. Deriving this in the query layer meant every consumer
-- re-implementing the same grouping.
CREATE OR REPLACE VIEW trade_lifecycles AS
SELECT correlation_id,
       min(seq)                                                   AS first_seq,
       min(ts)                                                    AS started_at,
       max(ts)                                                    AS last_at,
       count(*)                                                   AS event_count,
       max(payload->>'strategy') FILTER (
           WHERE type = 'strategy.signal_generated')              AS strategy,
       max(payload->>'symbol')   FILTER (
           WHERE type = 'strategy.signal_generated')              AS symbol,
       bool_or(type = 'strategy.signal_rejected')                 AS was_rejected,
       max(payload->>'code')     FILTER (
           WHERE type = 'strategy.signal_rejected')               AS reject_code,
       count(*) FILTER (WHERE type = 'execution.order_filled')    AS fill_count,
       coalesce(sum((payload->>'fee')::numeric) FILTER (
           WHERE type = 'execution.order_filled'), 0)             AS fees_paid,
       -- Fraction of filled quantity that rested as maker. The direct measure
       -- of whether the maker-first thesis (ARCHITECTURE.md §0.1) is real.
       -- The numerator MUST be coalesced. Without it an all-taker lifecycle
       -- yields NULL (no rows match the maker filter) rather than 0, so a
       -- dashboard averaging this column silently drops exactly the trades
       -- with the worst execution and reports a maker ratio better than
       -- reality. Caught against live Postgres 2026-07-27.
       CASE WHEN coalesce(sum((payload->>'qty')::numeric) FILTER (
                     WHERE type = 'execution.order_filled'), 0) > 0
            THEN coalesce(sum((payload->>'qty')::numeric) FILTER (
                     WHERE type = 'execution.order_filled'
                       AND (payload->>'is_maker')::boolean), 0)
                 / sum((payload->>'qty')::numeric) FILTER (
                     WHERE type = 'execution.order_filled')
       END                                                        AS maker_ratio,
       bool_or(type = 'portfolio.position_closed')                AS is_closed,
       max((payload->>'net_pnl')::numeric) FILTER (
           WHERE type = 'portfolio.position_closed')              AS net_pnl
FROM events
WHERE correlation_id IS NOT NULL
GROUP BY correlation_id;

CREATE TABLE audit_log (
    id        bigserial PRIMARY KEY,
    ts        timestamptz NOT NULL DEFAULT now(),
    actor     text NOT NULL,
    action    text NOT NULL,
    target    text,
    before    jsonb,
    after     jsonb,
    ip        inet
);
CREATE INDEX ON audit_log (ts DESC);

-- ════════════════════════════════════════════════════════════════════════
-- Research: backtests, models, regimes, promotion
-- ════════════════════════════════════════════════════════════════════════

CREATE TABLE backtests (
    id           bigserial PRIMARY KEY,
    created_at   timestamptz NOT NULL DEFAULT now(),
    strategy     text NOT NULL,
    symbols      text[] NOT NULL,
    timeframe    text NOT NULL,
    start_ts     timestamptz NOT NULL,
    end_ts       timestamptz NOT NULL,
    params       jsonb NOT NULL,
    -- Reproducibility is enforced, not hoped for: same three hashes => same
    -- result, or there is a bug.
    params_hash  text NOT NULL,
    data_hash    text NOT NULL,
    code_git_sha text NOT NULL,
    cost_model   jsonb NOT NULL,
    metrics      jsonb NOT NULL,
    equity_curve jsonb,
    n_trials     integer NOT NULL DEFAULT 1,   -- feeds the Deflated Sharpe
    kind         text NOT NULL DEFAULT 'single', -- single|walkforward|montecarlo
    UNIQUE (strategy, params_hash, data_hash, code_git_sha, kind)
);

CREATE TABLE regimes (
    exchange text NOT NULL,
    symbol   text NOT NULL,
    timeframe text NOT NULL,
    ts       timestamptz NOT NULL,
    regime   market_regime NOT NULL,
    prob     numeric(8,6),
    model_version text NOT NULL,
    PRIMARY KEY (exchange, symbol, timeframe, ts)
);
SELECT create_hypertable('regimes', 'ts', chunk_time_interval => interval '90 days');

CREATE TABLE model_registry (
    id          bigserial PRIMARY KEY,
    name        text NOT NULL,          -- 'meta_label_ema_cross'
    version     text NOT NULL,
    kind        text NOT NULL,          -- 'lightgbm'|'hmm'|'garch'
    path        text NOT NULL,
    trained_at  timestamptz NOT NULL DEFAULT now(),
    train_start timestamptz,
    train_end   timestamptz,
    oos_metrics jsonb NOT NULL,
    baseline_metrics jsonb NOT NULL,     -- the no-model comparison; §8
    is_active   boolean NOT NULL DEFAULT false,
    UNIQUE (name, version)
);

-- Recomputed nightly by qd-worker. The engine refuses live orders for a
-- strategy whose row here is not `passed`, unless arming used --force.
CREATE TABLE promotion_status (
    strategy       text PRIMARY KEY,
    evaluated_at   timestamptz NOT NULL DEFAULT now(),
    passed         boolean NOT NULL,
    paper_days     integer NOT NULL,
    paper_trades   integer NOT NULL,
    paper_sharpe   numeric(10,4),
    paper_max_dd   numeric(10,6),
    mc_p95_dd      numeric(10,6),
    bt_paper_corr  numeric(10,6),
    beats_benchmark boolean,
    failures       text[] NOT NULL DEFAULT '{}'
);

-- ════════════════════════════════════════════════════════════════════════
-- Continuous aggregate: hourly equity for the dashboard chart. Rendering a
-- 1-minute curve over a year in the browser is what kills these dashboards.
-- ════════════════════════════════════════════════════════════════════════
CREATE MATERIALIZED VIEW equity_hourly
WITH (timescaledb.continuous) AS
SELECT account_id,
       time_bucket(interval '1 hour', ts) AS bucket,
       first(equity, ts) AS open_equity,
       max(equity)       AS high_equity,
       min(equity)       AS low_equity,
       last(equity, ts)  AS close_equity,
       max(drawdown)     AS max_drawdown
FROM equity_curve
GROUP BY account_id, bucket
WITH NO DATA;

SELECT add_continuous_aggregate_policy('equity_hourly',
    start_offset => interval '7 days',
    end_offset   => interval '1 hour',
    schedule_interval => interval '1 hour');

